//! `cargo xtask parity`: write docs/parity/parity-checklist.md from the live command registry compared
//! with the word-processor feature catalog, both in `kition-doc-engine`.

use serde_json::Value;
use std::path::Path;

fn parity_markdown(p: &Value) -> String {
    let mut s = String::from(
        "# Kition Doc feature parity\n\nGenerated by `cargo xtask parity`: the word-processor feature catalog (`crates/engine/engine/src/catalog.rs`) compared with the live command registry.\n\n",
    );
    s += &format!(
        "**{} of {} catalog features have commands ({}%).**\n\n| Tab | Live | Total |\n|---|---|---|\n",
        p["live"], p["total"], p["percent"]
    );
    for t in p["tabs"].as_array().cloned().unwrap_or_default() {
        s += &format!("| {} | {} | {} |\n", t["tab"].as_str().unwrap_or(""), t["live"], t["total"]);
    }
    s += "\n## Missing\n\n";
    for t in p["tabs"].as_array().cloned().unwrap_or_default() {
        let m = t["missing"].as_array().cloned().unwrap_or_default();
        if m.is_empty() {
            continue;
        }
        s += &format!("### {}\n\n", t["tab"].as_str().unwrap_or(""));
        for x in m {
            s += &format!("- {}\n", x.as_str().unwrap_or(""));
        }
        s += "\n";
    }
    s
}

pub fn run(root: &Path) -> Result<(), String> {
    let reg = kition_doc_engine::cmd::registry();
    let p = kition_doc_engine::catalog::parity(&reg);
    let md = parity_markdown(&p);
    let path = root.join("docs/parity/parity-checklist.md");
    std::fs::write(&path, &md).map_err(|e| format!("{}: {e}", path.display()))?;
    if let Some(line) = md.lines().find(|l| l.starts_with("**")) {
        println!("{line}");
    }
    println!("wrote {}", path.display());
    Ok(())
}
